  readonly icon: "folder" | "chip" | "gauge";
  readonly depth: number;
  readonly expandable: boolean;
  readonly expanded: boolean;
}

export function visibleOutline(
  roots: readonly OutlineNode[],
  expanded: ReadonlySet<string>,
): readonly OutlineRow[] {
  const ids = new Set<string>();
  const active = new Set<OutlineNode>();
  const validate = (node: OutlineNode): void => {
    if (
      node.id.trim().length === 0 ||
      node.label.trim().length === 0 ||
      ids.has(node.id) ||
      active.has(node)
    ) {
      throw new RangeError("Invalid outline");
    }
    ids.add(node.id);
    active.add(node);
    for (const child of node.children) validate(child);
    active.delete(node);
  };
  for (const root of roots) validate(root);

  const icons = { group: "folder", device: "chip", metric: "gauge" } as const;
  const rows: OutlineRow[] = [];
  const visit = (node: OutlineNode, depth: number): void => {
    const expandable = node.children.length > 0;
    const isExpanded = expandable && expanded.has(node.id);
    rows.push({
      id: node.id,
      label: node.label,
      icon: icons[node.kind],
      depth,
      expandable,
      expanded: isExpanded,
    });
    if (expandable) {
      for (const child of node.children) visit(child, depth + 1);
    }
  };
  for (const root of roots) visit(root, 0);
  return rows;
}

