import { visibleOutline } from "./solution";

type MutableNode = {
  id: string;
  label: string;
  kind: "group" | "device" | "metric";
  children: MutableNode[];
};

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertJson(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

const roots: MutableNode[] = [
  {
    id: "g1", label: "Group", kind: "group", children: [
      { id: "d1", label: "Device", kind: "device", children: [
        { id: "m1", label: "Metric", kind: "metric", children: [] },
      ] },
      { id: "m2", label: "Second", kind: "metric", children: [] },
    ],
  },
  { id: "d2", label: "Other", kind: "device", children: [] },
];
const rows = visibleOutline(roots, new Set(["g1", "d1", "m1", "d2"]));
assertJson(rows, [
  { id: "g1", label: "Group", icon: "folder", depth: 0, expandable: true, expanded: true },
  { id: "d1", label: "Device", icon: "chip", depth: 1, expandable: true, expanded: true },
  { id: "m1", label: "Metric", icon: "gauge", depth: 2, expandable: false, expanded: false },
  { id: "m2", label: "Second", icon: "gauge", depth: 1, expandable: false, expanded: false },
  { id: "d2", label: "Other", icon: "chip", depth: 0, expandable: false, expanded: false },
], "pre-order traversal, icons, depth, and leaf expansion rules");
assertJson(visibleOutline(roots, new Set()), [
  { id: "g1", label: "Group", icon: "folder", depth: 0, expandable: true, expanded: false },
  { id: "d2", label: "Other", icon: "chip", depth: 0, expandable: false, expanded: false },
], "collapsed roots hide descendants");
assertJson(visibleOutline([], new Set()), [], "empty roots");
assertJson(roots[0].children[0], {
  id: "d1", label: "Device", kind: "device", children: [
    { id: "m1", label: "Metric", kind: "metric", children: [] },
  ],
}, "input nodes are not mutated");

const mutableRows = rows as Array<{ id: string; label: string; icon: string; depth: number; expandable: boolean; expanded: boolean }>;
mutableRows[0].label = "Changed";
assert(roots[0].label === "Group", "rows must not expose node objects");

function expectInvalid(nodes: MutableNode[], message: string): void {
  let threw = false;
  try {
    visibleOutline(nodes, new Set());
  } catch (error: unknown) {
    threw = error instanceof RangeError && error.message === "Invalid outline";
  }
  assert(threw, message);
}

expectInvalid([{ id: " ", label: "Valid", kind: "group", children: [] }], "blank id");
expectInvalid([{ id: "valid", label: "\t", kind: "group", children: [] }], "blank label");
expectInvalid([{ id: "root", label: "Root", kind: "group", children: [
  { id: "dup", label: "One", kind: "metric", children: [] },
  { id: "dup", label: "Two", kind: "metric", children: [] },
] }], "hidden duplicate ids must be validated");
const cyclic: MutableNode = { id: "cycle", label: "Cycle", kind: "group", children: [] };
cyclic.children.push(cyclic);
expectInvalid([cyclic], "hidden cyclic references must be validated");

